-- ADR-009 P4 条件结构化：SYSQR_DEFAULT 存量 F_TYPE/F_EXPR DSL → FILTER_TEMPLATE 转换（2026-08-30 工具生成）
--       本迁移由 ReportConditionTemplateBackfillTool 生成（563 行自动转换），
--       失败行保持 FILTER_TEMPLATE=NULL（运行期 fail-closed），入 logs/report-condition-migration/manual-list.csv。
-- 漂移守卫：LEGACY 原文一致且 FILTER_TEMPLATE 仍为 NULL 才落，不覆盖已人工配置值。

SET NOCOUNT ON;

DECLARE @GUARD_MESSAGE NVARCHAR(400) = N'本脚本只能在 EOS.ERP 数据库内执行，当前库为 ' + DB_NAME() + N'。';
IF DB_NAME() <> N'EOS.ERP'
    THROW 50000, @GUARD_MESSAGE, 1;

BEGIN TRANSACTION;

-- 1. SYSQR_DEFAULT 加 FILTER_TEMPLATE 列
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('dbo.SYSQR_DEFAULT') AND name = 'FILTER_TEMPLATE')
    ALTER TABLE dbo.SYSQR_DEFAULT ADD [FILTER_TEMPLATE] NVARCHAR(MAX) NULL;

-- 2. 存量转换（漂移守卫：LEGACY 原文一致且 FILTER_TEMPLATE 仍为 NULL 才落）
CREATE TABLE #TEMPLATE (M_IDX INT NOT NULL, SERIAL_NO INT NOT NULL, LEGACY NVARCHAR(MAX) NOT NULL, TEMPLATE NVARCHAR(MAX) NOT NULL);

UPDATE dbo.SYSQR_DEFAULT
SET FILTER_TEMPLATE = t.TEMPLATE
FROM dbo.SYSQR_DEFAULT d
INNER JOIN #TEMPLATE t ON t.M_IDX = d.M_IDX AND t.SERIAL_NO = d.SERIAL_NO
WHERE d.FILTER_TEMPLATE IS NULL
  AND LTRIM(RTRIM(ISNULL(CAST(d.F_TYPE AS NVARCHAR(10)),''))) + '|' + LTRIM(RTRIM(ISNULL(d.F_EXPR,''))) = t.LEGACY;

DROP TABLE #TEMPLATE;

-- 3. 扩展属性
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id = OBJECT_ID('dbo.SYSQR_DEFAULT') AND minor_id = (SELECT column_id FROM sys.columns WHERE object_id = OBJECT_ID('dbo.SYSQR_DEFAULT') AND name = 'FILTER_TEMPLATE'))
    EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'结构化参数定义（ADR-009 §6，FILTER_TEMPLATE JSON，复用 ADR-008 契约 + {p.X} 参数占位符）', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'SYSQR_DEFAULT', @level2type = N'COLUMN', @level2name = N'FILTER_TEMPLATE';

COMMIT TRANSACTION;
